{
  "status": "answered",
  "summary": "The handbook lists the visual items examined during a hot‑section (combustion and turbine) inspection.",
  "claims": [
    {
      "text": "Inspect the external combustion case for hot spots, exhaust leaks, and distortions before opening it.",
      "citations": [1]
    },
    {
      "text": "After opening, inspect combustion chambers for localized overheating, cracks, or excessive wear.",
      "citations": [1]
    },
    {
      "text": "Inspect first‑stage turbine blades and nozzle guide vanes for cracks, warping, or foreign‑object damage (FOD).",
      "citations": [1]
    },
    {
      "text": "Inspect combustion‑chamber outlet ducts and turbine nozzle for cracks and evidence of FOD.",
      "citations": [1]
    },
    {
      "text": "Inspect guide‑vanes and swirl‑vanes, especially trailing edges, for cracks or damage caused by foreign objects.",
      "citations": [1]
    },
    {
      "text": "Inspect the exhaust cone and exhaust nozzle for cracks, warping, buckling, or hot spots.",
      "citations": [2]
    }
  ],
  "gaps": "",
  "manufacturer_note": ""
}

{
