{
  "status": "answered",
  "summary": "The passages explain that C‑MAPSS simulates engine degradation by imposing exponential loss on flow and efficiency parameters, starting from a small random initial deterioration, adding process and measurement noise, and terminating the simulation when the health index reaches zero (the failure threshold).",
  "claims": [
    {
      "text": "Degradation is modeled by varying the efficiency (e) and flow (f) parameters of the engine modules with an exponential rate of change.",
      "citations": [4, 5]
    },
    {
      "text": "Initial deterioration values (e0, f0) are randomly selected within a 1 % deviation from the healthy condition.",
      "citations": [5]
    },
    {
      "text": "Process noise and measurement noise are superimposed on the simulated sensor outputs to mimic realistic conditions.",
      "citations": [5]
    },
    {
      "text": "The simulation stops when the health index H(t) reaches zero, which is defined as the failure criterion.",
      "citations": [5, 3]
    }
  ],
  "gaps": "",
  "manufacturer_note": ""
}

